import{_ as l,l as o,o as e,c as p,v as i,p as n,x as r,d as s,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"合谋与卡特尔","description":"","frontmatter":{"title":"合谋与卡特尔","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/collusion-cartel.md","filePath":"econ/collusion-cartel.md","lastUpdated":1789023840000}'),E={name:"econ/collusion-cartel.md"};function _(m,a,h,A,B,u){const t=o("Mermaid");return e(),p("div",null,[a[1]||(a[1]=i('<h1 id="合谋与卡特尔" tabindex="-1">合谋与卡特尔 <a class="header-anchor" href="#合谋与卡特尔" aria-label="Permalink to &quot;合谋与卡特尔&quot;">​</a></h1><div class="epigraph"><p>秘密降价的诱惑随买家数目与监测难度上升；静态伯川德把垄断价喊碎，重复互动才可能把它撑住。</p><footer>—— 据 Stigler, A Theory of Oligopoly, JPE, 1964；Friedman, A Non-cooperative Equilibrium for Supergames, RES, 1971 整理</footer></div><p>定位：<a href="/econ/bertrand-capacity">上一课</a>。同质、产能无限时同时喊价落到 \\(P=\\mathrm{MC}\\)；产能预承诺可以把产量读回古诺。本课不重讲配给规则与 Kreps–Scheinkman。缺口是：静态博弈里垄断价不是相互最优，卡特尔协议在一次性伯川德里不可自我实施。要把垄断价撑住，必须换时间结构——接到<a href="/econ/folk-theorem">重复博弈</a>，本课只写产业组织这一侧。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>卡特尔想实施垄断产量 \\(Q_m\\) 与价格 \\(P_m\\)，再按配额分 \\(\\pi_m\\)。静态里每家的最优偏离是：别人守约时，自己略微底切（伯川德）或把自己的产量扩到剩余需求的 \\(\\mathrm{MR}=\\mathrm{MC}\\)（古诺）。利润从份额变成几乎整块垄断剩余，一次性没有惩罚，合谋崩溃。缺口不是再定义一次 MR，而是：<strong>静态无法维持 \\(P_m\\)，维持需要可置信的未来损失。</strong></p><p>Stigler 把秘密降价写成信息不对称：卖方看不见对方的成交价，只看见自己的销量波动。买家越多、订单越碎，把降价伪装成需求冲击越容易，合谋越脆。这是监测问题，与无名氏定理的完美监测上界对照。</p><h3 id="卡特尔不是另一家垄断者" tabindex="-1">卡特尔不是另一家垄断者 <a class="header-anchor" href="#卡特尔不是另一家垄断者" aria-label="Permalink to &quot;卡特尔不是另一家垄断者&quot;">​</a></h3><p>把 \\(n\\) 家加总当成一家去读勒纳，漏掉激励相容。配额、补偿支付、共同销售机构，都是为了改偏离收益；没有这些，联合利润最大化只是规划，不是均衡。产能约束可以帮忙：打满的工厂底切空间小，合谋更容易——与上一课「产能把伯川德接回古诺」是同一把刀，方向变成「产能也挡住偏离」。</p><p><span class="marginnote">Friedman 的纳什回归：合作路径上要 \\(P_m\\)，一旦观测到偏离，永远回到阶段纳什（伯川德则是 \\(P=\\mathrm{MC}\\)）。贴现 \\(\\delta\\) 够大时，未来损失压过当期底切。本课不把无名氏集合整段搬来，只钉这一触发。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>阶段博弈取伯川德或古诺。合作支付 \\(\\pi_c\\)，偏离 \\(\\pi_d\\)，惩罚支付 \\(\\pi_p\\)（常取阶段纳什）。激励相容：</p> \\[\\pi_d-\\pi_c\\le\\frac{\\delta}{1-\\delta}(\\pi_c-\\pi_p). \\]<p>\\(\\delta\\) 越大、 \\((\\pi_c-\\pi_p)\\) 越大、当期偏离增益越小，合谋越容易。\\(n\\) 增加通常摊薄 \\(\\pi_c\\)、放大 \\(\\pi_d\\) 的相对诱惑。需求繁荣抬高当期偏离收益，Stigler–Rotemberg 一类比较静态说繁荣期更难合谋——声明监测假设后再用。</p><p>公开价格、同质大单、行业协会的信息交换，都是把监测从噪声里捞出来。本课不写反托拉斯条文，只写激励。</p>',14)),(e(),n(c,null,{default:r(()=>[d(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20STAT%5B%22%E9%9D%99%E6%80%81%E4%BC%AF%E5%B7%9D%E5%BE%B7%EF%BC%9AP%20%3D%20MC%22%5D%20--%3E%20DEV%5B%22%E5%AE%88%E7%BA%A6%E6%97%B6%E5%BA%95%E5%88%87%E6%9C%80%E6%9C%89%E5%88%A9%22%5D%0A%20%20DEV%20--%3E%20REP%5B%22%E9%87%8D%E5%A4%8D%20%2B%20%E8%A7%A6%E5%8F%91%E6%83%A9%E7%BD%9A%22%5D%0A%20%20REP%20--%3E%20IC%5B%22%CE%B4%20%E5%A4%A7%EF%BC%9AP_m%20%E5%8F%AF%E5%AE%9E%E6%96%BD%22%5D%0A%20%20IC%20--%3E%20MON%5B%22%E7%9B%91%E6%B5%8B%E5%B7%AE%EF%BC%9A%E7%A7%98%E5%AF%86%E9%99%8D%E4%BB%B7%EF%BC%8C%E9%9B%86%E5%90%88%E6%94%B6%E7%BC%A9%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<p>不要把「惩罚」写成限价簿上的掠夺性挂单；这里是产品市场的重复定价，没有时间优先队列。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>自我实施的机制是贴现：偏离赚一次 \\(\\pi_d-\\pi_c\\)，之后每期少赚 \\(\\pi_c-\\pi_p\\)。产能与差异改变的是 \\(\\pi_d\\)：差异越大，底切抢不到全部需求，偏离变钝，合谋可以更松——但差异也降低 \\(P_m\\) 相对竞争的升水，净效应要算。秘密降价的机制是信号提取：观测不到对方的 \\(p\\)，只能对销量做假设检验，惩罚会误伤，于是均衡必须掺噪声、效率下降。</p><p>与斯塔克尔伯格无关：合谋是对称的重复，不是先动承诺。指定一家「领导报价」若可观测、可惩罚，只是合谋的交流装置，不要写成<a href="/econ/stackelberg">产量领导</a>的反应曲线切点。</p><p>产能的另一面：过剩产能使惩罚更狠（偏离后可以立刻扩产砸价），也使当期偏离更诱人。经验上「过剩产能支撑卡特尔」不是定理，要看惩罚与偏离哪一头升得更快。产品同质、公开报价、买方集中，Stigler 的监测更易；碎买家、秘密折扣，触发策略的观测失败，无名氏集合收缩。</p><p><span class="marginnote">Stigler 1964 强调买方侧的信息结构，不是博弈论触发策略。Friedman 1971 才把超博弈均衡写清楚。两篇合在一起：激励相容加监测。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>有限次重复、阶段纳什唯一时，逆向归纳钉死竞争；有限次要合谋，需要阶段有多个纳什或声誉。反垄断的宽赦、私人诉讼改变 \\(\\pi_d\\) 的法律期望，本课不写。后课<a href="/econ/limit-pricing">限制进入定价</a>对付的是潜在进入者，不是在位者之间的配额。</p><p>后课默认：静态伯川德（或古诺）撑不住卡特尔；重复加监测才可能。无名氏定理给出可能性，不给出哪一个卡特尔会被选中。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>静态价格战把 \\(P_m\\) 底切掉；合谋是重复博弈的激励相容。</li><li>监测越差、买家越碎，秘密降价越容易，卡特尔越脆。</li><li>产能与差异改偏离收益，不改「需要未来惩罚」这一层。</li><li>下一课让一家先动，把同时选择改成可观察的产量承诺。</li><li>出处：Stigler, <em>JPE</em>, 1964；Friedman, <em>RES</em>, 1971。</li></ul>',11))])}const C=l(E,[["render",_]]);export{P as __pageData,C as default};
